VALUES 
  (gen_random_uuid(), '00000000-0000-0000-0000-000000000000', '52105dcc-f21a-4b2c-93fd-11d33b830aaa', 'HEADING', 0, '{"text":"שיעור קבלה: ספירת העומר ומוחין דקטנות","level":1}', NOW(), NOW()),
  (gen_random_uuid(), '00000000-0000-0000-0000-000000000000', '52105dcc-f21a-4b2c-93fd-11d33b830aaa', 'TEXT', 1, '{"text":"שיעור מאת מרן הרב ישראל, יום ה כב ניסן תשפ\"ו. הרב דן בנושאי מוחין דקטנות ומוחין דגדלות בתקופת ספירת העומר. מוחין דקטנות הוא מצב רוחני שבו האדם נמצא בשפל, אולם על פי הקבלה מדובר בשלב הכרחי של הכנה לגדלות. שיעור זה נלמד ביום כב ניסן תשפ\"ו בישיבת בית אל ירושלים."}', NOW(), NOW()),
  (gen_random_uuid(), '00000000-0000-0000-0000-000000000000', '52105dcc-f21a-4b2c-93fd-11d33b830aaa', 'TEXT', 2, '{"text":"תמצות השיעור: הרב דן במוחין דקטנות ומוחין דגדלות. מוחין דקטנות הוא מצב שבו האדם חי ללא מודעות לאלוקות, מצב שפל שמצד אחד הוא שלילי אך מצד שני הכרחי להתפתחות הרוחנית. בתקופת ספירת העומר, עם ישראל עובר ממצב קטנות (יציאת מצרים) לגדלות (קבלת התורה). הנקודות העיקריות: 1. מוחין דקטנות כמצב ביניים הכרחי. 2. ספירת העומר כתהליך של העלאת מוחין. 3. הקשר בין ימי הספירה לספירות הקבלה. 4. חשיבות הכוונה בעבודת הספירה."}', NOW(), NOW())
